//! Object (model) banks `objects/<bank>.dll`.
//!
//! The banks are Win32 PE DLLs holding only compiled C data generated by
//! `BankManager` (no code is ever executed here). The single export
//! `GetbankAddress` is `push ebp; mov ebp,esp; mov eax,imm32; pop ebp; ret`;
//! `imm32` is the virtual address of an `MDX_OBJECT_DESCRIPTOR[]` terminated
//! by a null controller. All pointers are absolute VAs relative to the
//! image base; we translate them through the section table.
//!
//! Struct layouts (MSVC x86, 4-byte pointers) from `MDX Library/mdxObject.h`;
//! loader `LoadObjBank` / `RestoreObjectPointers` in `mdxObject.cpp`.

use crate::read::{cstr, Error, Result};

#[derive(Clone, Copy, Debug)]
struct Section {
    va: u32,
    vsize: u32,
    raw_off: u32,
    raw_size: u32,
}

/// A mapped PE image (sections laid out at their RVAs, zero-filled like the
/// Windows loader does): read little-endian values at virtual addresses.
pub struct PeImage<'a> {
    data: &'a [u8],
    image: Vec<u8>,
    /// Addresses (VA) of every HIGHLOW base relocation: the fields that really hold pointers.
    relocs: std::collections::HashSet<u32>,
    pub image_base: u32,
    sections: Vec<Section>,
    exports: Vec<(String, u32)>,
}

fn le32(d: &[u8], o: usize) -> Option<u32> {
    d.get(o..o + 4).map(|b| u32::from_le_bytes(b.try_into().unwrap()))
}
fn le16(d: &[u8], o: usize) -> Option<u16> {
    d.get(o..o + 2).map(|b| u16::from_le_bytes(b.try_into().unwrap()))
}

fn perr(m: impl Into<String>) -> Error {
    Error::new("pe", m.into())
}

impl<'a> PeImage<'a> {
    pub fn parse(data: &'a [u8]) -> Result<PeImage<'a>> {
        if data.get(0..2) != Some(b"MZ") {
            return Err(perr("missing MZ header"));
        }
        let pe = le32(data, 0x3c).ok_or_else(|| perr("truncated"))? as usize;
        if data.get(pe..pe + 4) != Some(b"PE\0\0") {
            return Err(perr("missing PE signature"));
        }
        let nsec = le16(data, pe + 6).ok_or_else(|| perr("truncated"))? as usize;
        let opt_size = le16(data, pe + 20).ok_or_else(|| perr("truncated"))? as usize;
        let opt = pe + 24;
        if le16(data, opt) != Some(0x10b) {
            return Err(perr("not a PE32 image"));
        }
        let image_base = le32(data, opt + 28).ok_or_else(|| perr("truncated"))?;
        let mut sections = Vec::with_capacity(nsec);
        for i in 0..nsec {
            let s = opt + opt_size + i * 40;
            sections.push(Section {
                vsize: le32(data, s + 8).ok_or_else(|| perr("truncated section table"))?,
                va: le32(data, s + 12).ok_or_else(|| perr("truncated section table"))?,
                raw_size: le32(data, s + 16).ok_or_else(|| perr("truncated section table"))?,
                raw_off: le32(data, s + 20).ok_or_else(|| perr("truncated section table"))?,
            });
        }
        let size_of_image = le32(data, opt + 56).ok_or_else(|| perr("truncated"))? as usize;
        if size_of_image > 64 << 20 {
            return Err(perr(format!("implausible SizeOfImage {size_of_image}")));
        }
        let mut image = vec![0u8; size_of_image];
        for s in &sections {
            let n = s.raw_size.min(s.vsize.max(s.raw_size)) as usize;
            let src = data.get(s.raw_off as usize..s.raw_off as usize + n).ok_or_else(|| perr("section beyond file"))?;
            let dst = image.get_mut(s.va as usize..s.va as usize + n).ok_or_else(|| perr("section beyond SizeOfImage"))?;
            dst.copy_from_slice(src);
        }
        let mut relocs = std::collections::HashSet::new();
        let (rel_rva, rel_size) = (le32(data, opt + 136).unwrap_or(0) as usize, le32(data, opt + 140).unwrap_or(0) as usize);
        if rel_rva != 0 {
            let blk_all = image.get(rel_rva..rel_rva + rel_size).ok_or_else(|| perr("reloc table outside image"))?;
            let mut o = 0;
            while o + 8 <= blk_all.len() {
                let page = le32(blk_all, o).unwrap();
                let bs = le32(blk_all, o + 4).unwrap() as usize;
                if bs < 8 {
                    break;
                }
                for k in 0..(bs - 8) / 2 {
                    let e = le16(blk_all, o + 8 + 2 * k).unwrap_or(0);
                    if e >> 12 == 3 {
                        relocs.insert(image_base + page + u32::from(e & 0xfff));
                    }
                }
                o += bs;
            }
        }
        let mut img = PeImage { data, image, relocs, image_base, sections, exports: Vec::new() };
        let exp_rva = le32(data, opt + 96).unwrap_or(0);
        if exp_rva != 0 {
            let e = img.rva_off(exp_rva).ok_or_else(|| perr("export directory unmapped"))?;
            let nnames = le32(data, e + 24).unwrap_or(0) as usize;
            let funcs = le32(data, e + 28).unwrap_or(0);
            let names = le32(data, e + 32).unwrap_or(0);
            let ords = le32(data, e + 36).unwrap_or(0);
            for i in 0..nnames.min(4096) {
                let nrva = img.rd32_rva(names + 4 * i as u32)?;
                let ord = img.rd16_rva(ords + 2 * i as u32)? as u32;
                let frva = img.rd32_rva(funcs + 4 * ord)?;
                let no = img.rva_off(nrva).ok_or_else(|| perr("export name unmapped"))?;
                img.exports.push((cstr(&data[no..]), frva));
            }
        }
        Ok(img)
    }

    fn rva_off(&self, rva: u32) -> Option<usize> {
        self.sections.iter().find_map(|s| {
            let span = s.vsize.max(s.raw_size);
            if rva >= s.va && rva < s.va + span {
                let o = rva - s.va;
                // Bytes past raw_size are zero-filled in memory; we don't map them.
                if o < s.raw_size {
                    return Some((s.raw_off + o) as usize);
                }
            }
            None
        })
    }

    fn rd32_rva(&self, rva: u32) -> Result<u32> {
        self.rva_off(rva).and_then(|o| le32(self.data, o)).ok_or_else(|| perr(format!("rva {rva:#x} unmapped")))
    }
    fn rd16_rva(&self, rva: u32) -> Result<u16> {
        self.rva_off(rva).and_then(|o| le16(self.data, o)).ok_or_else(|| perr(format!("rva {rva:#x} unmapped")))
    }

    /// File offset of a virtual address.
    pub fn va_off(&self, va: u32) -> Option<usize> {
        va.checked_sub(self.image_base).and_then(|rva| self.rva_off(rva))
    }

    pub fn bytes(&self, va: u32, n: usize) -> Result<&[u8]> {
        let rva = va.checked_sub(self.image_base).ok_or_else(|| perr(format!("va {va:#x} below image base")))? as usize;
        self.image.get(rva..rva + n).ok_or_else(|| perr(format!("va {va:#x}+{n} outside image")))
    }
    pub fn u32(&self, va: u32) -> Result<u32> {
        Ok(u32::from_le_bytes(self.bytes(va, 4)?.try_into().unwrap()))
    }
    pub fn i32(&self, va: u32) -> Result<i32> {
        Ok(self.u32(va)? as i32)
    }
    pub fn i16(&self, va: u32) -> Result<i16> {
        Ok(i16::from_le_bytes(self.bytes(va, 2)?.try_into().unwrap()))
    }
    pub fn u8(&self, va: u32) -> Result<u8> {
        Ok(self.bytes(va, 1)?[0])
    }
    pub fn f32(&self, va: u32) -> Result<f32> {
        Ok(f32::from_bits(self.u32(va)?))
    }

    /// Reads a pointer field: `None` for null or for fields the linker did not
    /// relocate (stale tool data such as `bBox` in some banks is not a pointer).
    pub fn ptr(&self, va: u32) -> Result<Option<u32>> {
        let v = self.u32(va)?;
        Ok(if v != 0 && (self.relocs.is_empty() || self.relocs.contains(&va)) { Some(v) } else { None })
    }

    pub fn export(&self, name: &str) -> Option<u32> {
        self.exports.iter().find(|e| e.0 == name).map(|e| e.1 + self.image_base)
    }
}

pub type Vec3 = [f32; 3];
pub type Quat = [f32; 4];
pub type Mat4 = [[f32; 4]; 4];

#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[derive(Clone, Debug, PartialEq)]
pub struct VKey {
    pub v: Vec3,
    pub time: i32,
}

#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[derive(Clone, Debug, PartialEq)]
pub struct QKey {
    pub q: Quat,
    pub time: i32,
}

/// `MDX_MESH`. Per-face data is stored in the original (unsorted) order; the
/// game sorts faces by texture at load time, which only affects draw order.
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[derive(Clone, Debug, PartialEq)]
pub struct Mesh {
    pub vertices: Vec<Vec3>,
    /// Vertex indices, one triangle per face.
    pub faces: Vec<[i16; 3]>,
    /// 3 per face; UV = value × 0.000975 (≈ 1/1024).
    pub face_uv: Vec<[i16; 2]>,
    pub normals: Vec<Vec3>,
    /// RGBA floats, 3 per face.
    pub colors: Vec<Quat>,
    pub face_flags: Vec<u8>,
    /// Texture CRC per face (0 = none).
    pub textures: Vec<u32>,
}

#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[derive(Clone, Debug, PartialEq)]
pub struct ObjSprite {
    pub texture: u32,
    pub pos: [i16; 3],
    pub size: [i16; 2],
    pub offset: [i16; 2],
    pub flags: i16,
}

/// `MDX_OBJECT`: a node of the model hierarchy.
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[derive(Clone, Debug, PartialEq)]
pub struct Object {
    pub id: u32,
    pub name: String,
    pub xlu: u8,
    pub sprites: Vec<ObjSprite>,
    pub mesh: Option<Mesh>,
    /// Skinned models: indices into the root mesh this bone moves.
    pub effected_verts: Vec<i32>,
    pub scale_keys: Vec<VKey>,
    pub move_keys: Vec<VKey>,
    pub rotate_keys: Vec<QKey>,
    pub bbox: Option<[Vec3; 8]>,
    pub phong: u32,
    pub flags: i16,
    pub matrix: Mat4,
    pub children: Vec<Object>,
}

#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[derive(Clone, Debug, PartialEq)]
pub struct Animation {
    pub start: i16,
    pub end: i16,
    pub speed: f32,
    pub looped: i32,
}

/// `MDX_OBJECT_CONTROLLER` plus its root object.
#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[derive(Clone, Debug, PartialEq)]
pub struct Model {
    pub id: u32,
    pub radius: f32,
    pub object_size: i16,
    pub root: Object,
    /// Objects chained to the root via `next`. MDX transforms them like the root
    /// (from the actor matrix, `TransformObject` recursing on `next`), so they are
    /// kept separate from `root.children`. Pre-order = root subtree, then these.
    pub root_siblings: Vec<Object>,
    pub animations: Vec<Animation>,
    pub loc_mesh: Option<Mesh>,
    pub is_skinned: bool,
    pub num_vtx: i16,
}

impl Model {
    /// Root object name without the bank tool's suffix.
    pub fn name(&self) -> &str {
        &self.root.name
    }
}

#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
#[derive(Clone, Debug)]
pub struct ObjectBank {
    pub models: Vec<Model>,
}

const MAX_KEYS: usize = 100_000;
const MAX_FACES: usize = 200_000;

fn mat4(img: &PeImage, va: u32) -> Result<Mat4> {
    let mut m = [[0f32; 4]; 4];
    for (i, row) in m.iter_mut().enumerate() {
        for (j, v) in row.iter_mut().enumerate() {
            *v = img.f32(va + 4 * (i * 4 + j) as u32)?;
        }
    }
    Ok(m)
}

fn vec3(img: &PeImage, va: u32) -> Result<Vec3> {
    Ok([img.f32(va)?, img.f32(va + 4)?, img.f32(va + 8)?])
}

fn quat(img: &PeImage, va: u32) -> Result<Quat> {
    Ok([img.f32(va)?, img.f32(va + 4)?, img.f32(va + 8)?, img.f32(va + 12)?])
}

fn mesh(img: &PeImage, va: u32) -> Result<Mesh> {
    let nf = img.i16(va)?;
    let nv = img.i16(va + 2)?;
    if nf < 0 || nv < 0 || nf as usize > MAX_FACES {
        return Err(perr(format!("mesh at {va:#x}: bad counts {nf}/{nv}")));
    }
    let (nf, nv) = (nf as usize, nv as usize);
    let p_vert = img.ptr(va + 4)?.unwrap_or(0);
    let p_face = img.ptr(va + 8)?.unwrap_or(0);
    let p_tc = img.ptr(va + 16)?.unwrap_or(0);
    let p_norm = img.ptr(va + 20)?.unwrap_or(0);
    let p_col = img.ptr(va + 24)?.unwrap_or(0);
    let p_flags = img.ptr(va + 28)?.unwrap_or(0);
    let p_tex = img.ptr(va + 32)?.unwrap_or(0);
    let vertices = if p_vert != 0 { (0..nv).map(|i| vec3(img, p_vert + 12 * i as u32)).collect::<Result<_>>()? } else { vec![] };
    let normals = if p_norm != 0 { (0..nv).map(|i| vec3(img, p_norm + 12 * i as u32)).collect::<Result<_>>()? } else { vec![] };
    let mut faces = Vec::with_capacity(nf);
    if p_face != 0 {
        for i in 0..nf as u32 {
            let f = [img.i16(p_face + 6 * i)?, img.i16(p_face + 6 * i + 2)?, img.i16(p_face + 6 * i + 4)?];
            for &ix in &f {
                if ix < 0 || ix as usize >= nv.max(1) {
                    return Err(perr(format!("mesh at {va:#x}: face {i} index {ix} out of {nv} vertices")));
                }
            }
            faces.push(f);
        }
    }
    let face_uv = if p_tc != 0 { (0..nf as u32 * 3).map(|i| Ok([img.i16(p_tc + 4 * i)?, img.i16(p_tc + 4 * i + 2)?])).collect::<Result<_>>()? } else { vec![] };
    let colors = if p_col != 0 { (0..nf as u32 * 3).map(|i| quat(img, p_col + 16 * i)).collect::<Result<_>>()? } else { vec![] };
    let face_flags = if p_flags != 0 { img.bytes(p_flags, nf)?.to_vec() } else { vec![] };
    let textures = if p_tex != 0 { (0..nf as u32).map(|i| img.u32(p_tex + 4 * i)).collect::<Result<_>>()? } else { vec![] };
    Ok(Mesh { vertices, faces, face_uv, normals, colors, face_flags, textures })
}

/// Reads an `MDX_OBJECT` and its `children` / `next` chains (as a tree).
fn object(img: &PeImage, va: u32, depth: u32) -> Result<(Object, u32)> {
    if depth > 256 {
        return Err(perr("object hierarchy too deep"));
    }
    let id = img.u32(va)?;
    let name = cstr(img.bytes(va + 4, 16)?);
    let xlu = img.u8(va + 22)?;
    let num_sprites = img.u8(va + 23)? as u32;
    let p_sprites = img.ptr(va + 24)?.unwrap_or(0);
    let p_mesh = img.ptr(va + 28)?.unwrap_or(0);
    let p_eff = img.ptr(va + 40)?.unwrap_or(0);
    let num_verts = img.i16(va + 48)?;
    let p_skeys = img.ptr(va + 52)?.unwrap_or(0);
    let p_mkeys = img.ptr(va + 56)?.unwrap_or(0);
    let p_rkeys = img.ptr(va + 60)?.unwrap_or(0);
    let (ns, nm, nr) = (img.i16(va + 64)?, img.i16(va + 66)?, img.i16(va + 68)?);
    let p_bbox = img.ptr(va + 72)?.unwrap_or(0);
    let phong = img.u32(va + 76)?;
    let flags = img.i16(va + 80)?;
    let p_children = img.ptr(va + 84)?.unwrap_or(0);
    let p_next = img.ptr(va + 88)?.unwrap_or(0);
    let matrix = mat4(img, va + 96)?;

    let vkeys = |p: u32, n: i16| -> Result<Vec<VKey>> {
        if p == 0 || n <= 0 {
            return Ok(vec![]);
        }
        if n as usize > MAX_KEYS {
            return Err(perr("too many keys"));
        }
        (0..n as u32).map(|i| Ok(VKey { v: vec3(img, p + 16 * i)?, time: img.i32(p + 16 * i + 12)? })).collect()
    };
    let scale_keys = vkeys(p_skeys, ns)?;
    let move_keys = vkeys(p_mkeys, nm)?;
    let rotate_keys = if p_rkeys != 0 && nr > 0 {
        (0..nr as u32).map(|i| Ok(QKey { q: quat(img, p_rkeys + 20 * i)?, time: img.i32(p_rkeys + 20 * i + 16)? })).collect::<Result<_>>()?
    } else {
        vec![]
    };
    let sprites = if p_sprites != 0 {
        (0..num_sprites)
            .map(|i| {
                let s = p_sprites + 24 * i;
                Ok(ObjSprite {
                    texture: img.u32(s)?,
                    pos: [img.i16(s + 8)?, img.i16(s + 10)?, img.i16(s + 12)?],
                    size: [img.i16(s + 14)?, img.i16(s + 16)?],
                    offset: [img.i16(s + 18)?, img.i16(s + 20)?],
                    flags: img.i16(s + 22)?,
                })
            })
            .collect::<Result<_>>()?
    } else {
        vec![]
    };
    let effected_verts = if p_eff != 0 && num_verts > 0 { (0..num_verts as u32).map(|i| img.i32(p_eff + 4 * i)).collect::<Result<_>>()? } else { vec![] };
    let bbox = if p_bbox != 0 {
        let mut b = [[0f32; 3]; 8];
        for (i, v) in b.iter_mut().enumerate() {
            *v = vec3(img, p_bbox + 12 * i as u32)?;
        }
        Some(b)
    } else {
        None
    };
    let mesh = if p_mesh != 0 { Some(mesh(img, p_mesh)?) } else { None };
    let mut children = Vec::new();
    let mut c = p_children;
    let mut guard = 0;
    while c != 0 {
        guard += 1;
        if guard > 4096 {
            return Err(perr("sibling chain too long"));
        }
        let (child, next) = object(img, c, depth + 1)?;
        children.push(child);
        c = next;
    }
    Ok((Object { id, name, xlu, sprites, mesh, effected_verts, scale_keys, move_keys, rotate_keys, bbox, phong, flags, matrix, children }, p_next))
}

impl ObjectBank {
    pub fn parse(data: &[u8]) -> Result<ObjectBank> {
        let img = PeImage::parse(data)?;
        let f = img.export("GetbankAddress").ok_or_else(|| perr("no GetbankAddress export"))?;
        let code = img.bytes(f, 16)?;
        let p = code.iter().position(|&b| b == 0xB8).filter(|&p| p <= 8).ok_or_else(|| perr("unexpected GetbankAddress code"))?;
        let mut desc = u32::from_le_bytes(code[p + 1..p + 5].try_into().unwrap());
        let mut models = Vec::new();
        for _ in 0..100_000 {
            let id = img.u32(desc)?;
            let ctl = img.u32(desc + 4)?;
            if ctl == 0 {
                break;
            }
            let p_obj = img.ptr(ctl + 12)?.unwrap_or(0);
            let radius = img.f32(ctl + 16)?;
            let object_size = img.i16(ctl + 8)?;
            let p_anim = img.ptr(ctl + 24)?.unwrap_or(0);
            let p_loc = img.ptr(ctl + 40)?.unwrap_or(0);
            let is_skinned = img.i16(ctl + 44)? != 0;
            let num_vtx = img.i16(ctl + 46)?;
            if p_obj == 0 {
                return Err(perr(format!("model {id:#x} has no object")));
            }
            let (root, next) = object(&img, p_obj, 0)?;
            let mut root_siblings = Vec::new();
            let mut c = next;
            while c != 0 {
                let (o, n) = object(&img, c, 1)?;
                root_siblings.push(o);
                c = n;
            }
            let animations = if p_anim != 0 {
                let n = img.i16(p_anim)?;
                let p = img.ptr(p_anim + 72)?.unwrap_or(0);
                if p != 0 && n > 0 {
                    (0..n as u32)
                        .map(|i| {
                            let a = p + 12 * i;
                            Ok(Animation { start: img.i16(a)?, end: img.i16(a + 2)?, speed: img.f32(a + 4)?, looped: img.i32(a + 8)? })
                        })
                        .collect::<Result<_>>()?
                } else {
                    vec![]
                }
            } else {
                vec![]
            };
            let loc_mesh = if p_loc != 0 { Some(mesh(&img, p_loc)?) } else { None };
            models.push(Model { id, radius, object_size, root, root_siblings, animations, loc_mesh, is_skinned, num_vtx });
            desc += 8;
        }
        Ok(ObjectBank { models })
    }

    pub fn find(&self, id: u32) -> Option<&Model> {
        self.models.iter().find(|m| m.id == id)
    }
}
